"""Swagger UI for the OpenAPI document generated by flask-smorest."""

from __future__ import annotations

from flask import jsonify
from flask_smorest import Api
from flask_swagger_ui import get_swaggerui_blueprint


SWAGGER_BLUEPRINT = get_swaggerui_blueprint(
    "/docs",
    "/openapi.json",
    config={"app_name": "RKM Service Manager API", "deepLinking": True},
)


def init_api(app) -> None:
    app.extensions["rkm_openapi"] = Api(
        app,
        spec_kwargs={
            "title": "RKM Service Manager API",
            "version": "0.1.0",
            "openapi_version": "3.0.3",
        },
    )


def register_api_docs(app) -> None:
    api = app.extensions["rkm_openapi"]
    app.add_url_rule(
        "/openapi.json",
        endpoint="openapi_json",
        view_func=lambda: jsonify(api.spec.to_dict()),
    )
    app.register_blueprint(SWAGGER_BLUEPRINT)
